local RunService = game:GetService("RunService")
local Character =  nil -- define ur character here

local function PlayAnim(Data, Model, Looped, Speed)
	local Frames = Data.Animation
	if not Frames or #Frames == 0 then return end

	local Motors = {}
	for _, Object in Model:GetDescendants() do
		local IsMotor = Object:IsA("Motor6D")
		local IsConstraint = Object:IsA("AnimationConstraint")
		if IsMotor or IsConstraint then
			local TargetPart = IsMotor and Object.Part1 or (Object.Attachment1 and Object.Attachment1.Parent or Object.Part1)
			if TargetPart then Motors[TargetPart.Name] = Object end
			Motors[Object.Name] = Object
		elseif Object:IsA("Bone") then
			Motors[Object.Name] = Object
		end
	end

	local IsR6 = Model:FindFirstChild("Torso") ~= nil
	if IsR6 then
		local R6Map = {
			UpperTorso = Motors["Torso"], LowerTorso = Motors["Torso"], Head = Motors["Head"],
			RightUpperArm = Motors["Right Arm"], RightLowerArm = Motors["Right Arm"], RightHand = Motors["Right Arm"],
			LeftUpperArm = Motors["Left Arm"], LeftLowerArm = Motors["Left Arm"], LeftHand = Motors["Left Arm"],
			RightUpperLeg = Motors["Right Leg"], RightLowerLeg = Motors["Right Leg"], RightFoot = Motors["Right Leg"],
			LeftUpperLeg = Motors["Left Leg"], LeftLowerLeg = Motors["Left Leg"], LeftFoot = Motors["Left Leg"]
		}
		for Key, Joint in R6Map do
			if not Motors[Key] then Motors[Key] = Joint end
		end
	end

	local MappedCount = 0
	for Name in Frames[1].Data do
		if Motors[Name] and Name ~= "HumanoidRootPart" then MappedCount += 1 end
	end
	if MappedCount == 0 then return end

	local Humanoid = Model:FindFirstChildOfClass("Humanoid")
	if Humanoid then
		local Animator = Humanoid:FindFirstChildOfClass("Animator")
		if Animator then
			for _, Track in Animator:GetPlayingAnimationTracks() do Track:Stop(0) end
		end
		local AnimateScript = Model:FindFirstChild("Animate")
		if AnimateScript and AnimateScript:IsA("LocalScript") then AnimateScript.Enabled = false end
	end

	local function GetFramePair(TargetTime)
		if #Frames == 1 or TargetTime <= Frames[1].Time then return Frames[1], Frames[1] end
		if TargetTime >= Frames[#Frames].Time then return Frames[#Frames], Frames[#Frames] end
		local Low, High = 1, #Frames - 1
		while Low <= High do
			local Mid = math.floor((Low + High) / 2)
			local A, B = Frames[Mid], Frames[Mid + 1]
			if TargetTime >= A.Time and TargetTime <= B.Time then return A, B end
			if TargetTime < A.Time then High = Mid - 1 else Low = Mid + 1 end
		end
		return Frames[1], Frames[1]
	end

	local Track = {Playing = true, Time = 0, Speed = Speed or 1, Length = Frames[#Frames].Time}
	local LastTick = os.clock()

	Track.Connection = RunService.PreSimulation:Connect(function()
		if not Track.Playing or not Model.Parent then return Track.Connection:Disconnect() end
		local Now = os.clock()
		local Dt = Now - LastTick
		LastTick = Now

		Track.Time += Dt * Track.Speed
		if Track.Time >= Track.Length then
			if Looped then Track.Time %= Track.Length else Track.Playing = false; return Track.Connection:Disconnect() end
		end

		local Prev, NextF = GetFramePair(Track.Time)
		local Delta = NextF.Time - Prev.Time
		local Alpha = (Delta > 0) and math.clamp((Track.Time - Prev.Time) / Delta, 0, 1) or 0

		for JointName, Joint in Motors do
			if JointName == "HumanoidRootPart" then continue end
			local Cf1, Cf2 = Prev.Data[JointName], NextF.Data[JointName]
			if Cf1 and Cf2 then
				Joint.Transform = Cf1:Lerp(Cf2, Alpha)
			elseif Cf1 or Cf2 then
				Joint.Transform = Cf1 or Cf2
			end
		end
	end)

	return Track
end

if not Character then Character = game:GetService("Players").LocalPlayer.Character or  game:GetService("Players").LocalPlayer.CharacterAdded:Wait() end

PlayAnim(AnimationData, Character, true, 1)
